  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shiseido.co.uk/gb/en/shiseido-affiliate-program.html', 'brand_official', 'affiliate_program_page', 'Shiseido''s own affiliate program page (fetched 2026-11-21) confirms the program: affiliates earn commission on purchases made through their links, with competitive rates, a 30-day cookie window, banners and a product feed, a dedicated affiliate program contact, and free signup followed by an application review. The page publishes no commission rate and no earnings-cap statement, so commission_rate is null and the cap is unknown.', 'verified', now());
