  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.skinceuticals.co.uk/en_GB/skinc-affiliates.html', 'brand_official', 'affiliate_program_page', 'SkinCeuticals'' own UK affiliate page invites sites to join the program and earn commission on sales, citing a 30-day cookie window, free joining, real-time reporting, scheduled payouts and dynamic commissions for high-selling affiliates. The page publishes no rate and no earnings-cap statement.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://marketplace.referly.so/affiliate-programs/skinceuticals', 'listing', 'affiliate_network_listing', 'Referly''s marketplace listing states the US program runs on CJ Affiliate with a 6% baseline commission and a 30-day cookie, and lists the program contact skinceuticals@cj.com; it also notes some directories cite a 5% payout instead, so the exact CJ rate is not settled.', 'publicly_reported', now());
