  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 12, 10, 10, 8, 5, '{"niche_fit": "Premium clinical skincare with hero serums \u2014 a top creator niche for expert-led skincare content.", "ugc_evidence": "The brand runs its own affiliate recruitment page and network programs aimed at publishers and creators; no creator count is published.", "compensation": "Reported baselines are 6% on CJ (US) and 5% on Awin (UK), with other sources claiming up to 10% \u2014 conflicting, so commission_rate is null and the cap is unknown.", "contact_access": "A program contact email (skinceuticals@cj.com) is published on the CJ listing, plus the brand''s own affiliate page.", "opportunity_availability": "Programs are open now on CJ Affiliate (US) and Awin (UK).", "credibility": "L''Or\u00e9al-owned, dermatologist-dispensed brand with decades of clinical positioning."}'::jsonb);
