  insert into public.brands (name, website, description, country, status) values ('BulkSupplements', 'https://www.bulksupplements.com', 'BulkSupplements.com (Hard Eight Nutrition LLC) sells 500+ pure single-ingredient dietary supplements and bulk powders — creatine, protein, vitamins, minerals and herbal extracts — at low prices through its own site and Amazon, with fulfillment centers in Las Vegas and Nashville.', 'United States', 'published') returning id into bid;
