  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 15, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://offers.maxfunnels.com/wp-content/uploads/2025/09/Become-a-BulkSupplements-Affiliate-Today.pdf.', null, 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'BulkSupplements Affiliate Program (via Awin)', null, 'https://offers.maxfunnels.com/wp-content/uploads/2025/09/Become-a-BulkSupplements-Affiliate-Today.pdf', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://offers.maxfunnels.com/wp-content/uploads/2025/09/Become-a-BulkSupplements-Affiliate-Today.pdf', 'official_site', 'affiliate', 'BulkSupplements.com''s own affiliate program page states: ''Our programs offer a lucrative 15% base commission on all sales associated with your links,'' identifies the brand as an ''AWIN top Power Rank merchant with thousands of sales a day and over 100,000 positive reviews,'' directs applicants to create an Awin publisher account and search for BulkSupplements.com, and says it is looking for ''bloggers, YouTubers, Instagram promoters, TikTok Creators and social media influencers.'' No earnings-cap statement appears, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://theaffiliateslist.com/supplement-affiliate-programs/', 'affiliate_network', 'compensation', 'The Affiliates List reports BulkSupplements pays 15% on standard retail sales and 2% on referred bulk/wholesale orders with a 90-day cookie — consistent with the brand''s own published 15% base rate, with a lower wholesale tier.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.creator-hero.com/blog/top-10-best-us-supplement-influencer-affiliate-programs', 'listing', 'affiliate', 'Creator Hero lists a 15% base commission and 2% wholesale rate but links signup through ShareASale, and another directory claims the program ''now runs through TikTok Shop'' — platform claims conflict across directories; the brand''s own affiliate page (Awin) governs, so the network is recorded as Awin.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 16, 9, 9, 5, '{"niche_fit": "Pure single-ingredient supplements and DIY stack ingredients are a staple of fitness and wellness creator content.", "ugc_evidence": "The brand''s own affiliate page explicitly recruits TikTok Creators, YouTubers and Instagram promoters, though no structured ambassador program is published.", "compensation": "A published 15% base commission on all sales from the brand''s own affiliate page (third parties report a 2% tier on wholesale/bulk orders).", "contact_access": "Application is via an Awin publisher account; no public partnerships email could be verified.", "opportunity_availability": "Open application through Awin to bloggers and social creators per the brand''s own page.", "credibility": "Established merchant (Hard Eight Nutrition LLC) claiming thousands of sales a day and 100,000+ reviews on its own page."}'::jsonb);
