  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/89125', 'affiliate_network', 'affiliate', 'Cronometer''s Awin merchant profile states affiliates ''get remunerated for lead generation, or signing up new users, and receive a commission on all Gold Subscription sales'': $0.10 per lead generated (new user signup through the referral link) plus 35% per transaction on Gold Subscriptions within 365 days of the signup referral. The profile publishes support@cronometer.com for program questions and notes the program does not work with coupon websites. No earnings-cap statement appears, so the cap is unknown.', 'verified', now());
