  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.Groupon.Co.Uk/discount-codes/dofasting', 'listing', 'compensation', 'Groupon''s DoFasting page describes the Affiliate Programme as starting at $20 per sale and rising to $45 with monthly performance bonuses, and a separate Ambassador programme starting at 20% per sale — multiple routes exist; the Impact listing''s $20 flat starting bounty is the recorded baseline.', 'publicly_reported', now());
