  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tokyotreat.refersion.com/', 'official_site', 'affiliate', 'TokyoTreat''s own Refersion affiliate portal terms confirm the program: last-click crediting, a 30-day referral/cookie period, payment via PayPal on the 10th of each month with a US$20 minimum, one Qualified Referral per referred customer (first purchase), and express permission to promote referral links ''on your own Youtube channel, social media accounts, blogs, and website'' (paid search on brand terms is banned). The portal does not publish the payout amount, and no earnings-cap statement appears, so the cap is unknown.', 'verified', now());
